window.smartAiAsset = function(value) {
 if(typeof value!=='string')return value;
 return value.replace(/(?:https:\/\/framerusercontent\.com|\/assets\/framerusercontent\.com)\/images\/([^? ,]+)/g,(match,name)=>window.smartAiAssets[name]||match);
};
window.smartAiText = function(value) {
 if(typeof value!=='string')return value;
 if(Object.prototype.hasOwnProperty.call(window.smartAiContent,value))return window.smartAiContent[value];
 if(value.startsWith('[')||value.startsWith('{')) {try {
  const walk=v=>typeof v==='string'?window.smartAiText(v):Array.isArray(v)?v.map(walk):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).map(([k,x])=>[k,walk(x)])):v;
  return JSON.stringify(walk(JSON.parse(value)));
 }catch{}}
 return window.smartAiAsset(value).replace(/\bMakro\b/g,'SmartAi Sales');
};
